<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,nextTick} from 'vue';
import {frameActive,readingMaterial} from './reading-context';import {activeCodeProvider} from './code-context';
const props=defineProps<{sectionId:string}>();const emit=defineEmits<{close:[]}>();
const box=ref({x:0,y:0,w:0,h:0}),capturing=ref(false),error=ref(''),surface=ref<HTMLElement>();let root:HTMLElement|undefined,start:{x:number;y:number;resize?:boolean}|undefined,disposed=false;
const style=computed(()=>({left:box.value.x+'px',top:box.value.y+'px',width:box.value.w+'px',height:box.value.h+'px'}));
const intersects=(a:DOMRect,b:{x:number;y:number;w:number;h:number})=>a.right>b.x&&a.left<b.x+b.w&&a.bottom>b.y&&a.top<b.y+b.h;
function rootAt(x:number,y:number){return document.elementsFromPoint(x,y).map(el=>el.closest<HTMLElement>('.study-article,.book-host .leaf-content')).find(el=>el&&el.getBoundingClientRect().width>0) as HTMLElement|undefined;}
function down(e:PointerEvent){if(e.button!==0||capturing.value||(e.target as HTMLElement).closest('button,input'))return;surface.value!.style.pointerEvents='none';root=rootAt(e.clientX,e.clientY);surface.value!.style.pointerEvents='';if(!root){error.value='请在可见书页内框选。';return;}e.preventDefault();start={x:e.clientX,y:e.clientY};box.value={x:e.clientX,y:e.clientY,w:0,h:0};surface.value!.setPointerCapture(e.pointerId);}
function move(e:PointerEvent){if(!start||!root)return;const r=root.getBoundingClientRect(),x=Math.max(0,r.left,Math.min(e.clientX,r.right,innerWidth)),y=Math.max(0,r.top,Math.min(e.clientY,r.bottom,innerHeight));box.value={x:Math.min(x,start.x),y:Math.min(y,start.y),w:Math.abs(x-start.x),h:Math.abs(y-start.y)};}
function up(){start=undefined;}
function paragraph(){const candidates=[...document.querySelectorAll<HTMLElement>('.study-article [data-block],.book-host .leaf-content [data-block]')];const block=candidates.find(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.top>=70&&r.top<innerHeight-120&&r.bottom>r.top&&!el.closest('[aria-hidden=true]');});if(!block){error.value='当前没有可选择的正文，请先进入章节。';return;}root=block.closest<HTMLElement>('.study-article,.leaf-content')!;const r=block.getBoundingClientRect();box.value={x:Math.max(0,r.left),y:Math.max(0,r.top),w:Math.min(r.width,innerWidth-r.left),h:Math.min(r.height,innerHeight-r.top-90)};}
function adjust(dimension:'w'|'h',value:number){if(!root)return;const r=root.getBoundingClientRect();box.value[dimension]=Math.max(20,Math.min(value,dimension==='w'?Math.min(r.right,innerWidth)-box.value.x:Math.min(r.bottom,innerHeight-80)-box.value.y));}
async function capture(){if(!root||box.value.w<10||box.value.h<10){error.value='请先框选正文，或使用选择当前段落。';return;}capturing.value=true;error.value='';let image='';const selection={...box.value},target=root,rect=root.getBoundingClientRect();
 const segments:string[]=[];const walker=document.createTreeWalker(target,NodeFilter.SHOW_TEXT);let node:Node|null;let length=0;
 while((node=walker.nextNode())&&length<12000){if(node.parentElement?.closest('button,script,style,.katex-html'))continue;const range=document.createRange();range.selectNodeContents(node);if([...range.getClientRects()].some(r=>intersects(r,selection))){const value=node.textContent||'';let chosen='';for(let i=0;i<value.length&&length<12000;i++){range.setStart(node,i);range.setEnd(node,i+1);if([...range.getClientRects()].some(r=>intersects(r,selection))){chosen+=value[i];length++;}}segments.push(chosen);}}
 const latex=[...target.querySelectorAll<HTMLElement>('[data-tex]')].filter(el=>intersects(el.getBoundingClientRect(),selection)).map(el=>el.dataset.tex).join('\n');
 const block=[...target.querySelectorAll<HTMLElement>('[data-block]')].find(el=>intersects(el.getBoundingClientRect(),selection));
 try{await document.fonts.ready;const {toSvg}=await import('html-to-image');const svgUrl=await toSvg(target,{width:target.offsetWidth,height:target.scrollHeight,style:{transform:'none',position:'relative',left:'0',top:'0',margin:'0'},filter:node=>!(node instanceof Element&&node.matches('button,.formula-copy,.page-number'))});
  const xml=new DOMParser().parseFromString(decodeURIComponent(svgUrl.slice(svgUrl.indexOf(',')+1)),'image/svg+xml');
  const svg=xml.documentElement;const foreign=svg.querySelector('foreignObject');foreign?.setAttribute('width',String(target.offsetWidth));foreign?.setAttribute('height',String(target.scrollHeight));const sx=target.offsetWidth/rect.width,sy=target.scrollHeight/rect.height;
  svg.setAttribute('viewBox',`${(selection.x-rect.left)*sx} ${(selection.y-rect.top)*sy} ${selection.w*sx} ${selection.h*sy}`);svg.setAttribute('width',String(selection.w));svg.setAttribute('height',String(selection.h));
  const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));await img.decode();
  const ratio=Math.min(2,2048/Math.max(selection.w,selection.h)),crop=document.createElement('canvas');crop.width=Math.ceil(selection.w*ratio);crop.height=Math.ceil(selection.h*ratio);const ctx=crop.getContext('2d')!;ctx.drawImage(img,0,0,crop.width,crop.height);const pixels=ctx.getImageData(0,0,crop.width,crop.height).data;let painted=false;for(let i=3;i<pixels.length;i+=4){if(pixels[i]){painted=true;break;}}if(!painted)throw Error('空白截图');ctx.globalCompositeOperation='destination-over';ctx.fillStyle='#f7eedb';ctx.fillRect(0,0,crop.width,crop.height);ctx.globalCompositeOperation='source-over';image=crop.toDataURL('image/png');if(image.length>2800000)image=crop.toDataURL('image/jpeg',.8);if(image.length>2800000)throw Error('选区图过大');
 }catch{error.value='截图未成功。文字和公式已提取，可重新框选，或明确选择仅发送文字。';}
 if(disposed)return;readingMaterial.value={version:crypto.randomUUID(),section_id:target.closest<HTMLElement>('[data-section]')?.dataset.section||props.sectionId,block_id:block?.dataset.block||'',text:segments.join(' ').slice(0,12000),latex:latex.slice(0,12000),image};capturing.value=false;
}
function accept(textOnly=false){if(!readingMaterial.value)return;if(textOnly)readingMaterial.value={...readingMaterial.value,image:''};activeCodeProvider.value=null;emit('close');nextTick(()=>window.dispatchEvent(new Event('plex-pet-open')));}
function cancel(){readingMaterial.value=null;emit('close');}
let previousFocus:HTMLElement|null=null;
function keys(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();cancel();}if(e.key==='Tab'){const targets=[...(surface.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input')||[])];const current=targets.indexOf(document.activeElement as HTMLElement);const next=(current+(e.shiftKey?-1:1)+targets.length)%targets.length;e.preventDefault();targets[next]?.focus();}}
onMounted(()=>{previousFocus=document.activeElement as HTMLElement;frameActive.value=true;document.addEventListener('keydown',keys,true);window.addEventListener('resize',cancel);nextTick(()=>surface.value?.querySelector<HTMLButtonElement>('button')?.focus());});onBeforeUnmount(()=>{disposed=true;frameActive.value=false;document.removeEventListener('keydown',keys,true);window.removeEventListener('resize',cancel);previousFocus?.focus({preventScroll:true});});
</script>
<template><div ref="surface" class="frame-reading" role="dialog" aria-modal="true" aria-label="框框阅读选区" @pointerdown="down" @pointermove="move" @pointerup="up"><div class="frame-reading-tools"><strong>框框阅读 · 仅当前书页</strong><button @click="paragraph">选择当前段落</button><button :disabled="capturing" @click="capture">{{capturing?'正在生成预览':'预览选区'}}</button><button @click="cancel">取消框选</button><label>宽<input type="range" min="20" :max="1600" :value="box.w" @input="adjust('w',Number(($event.target as HTMLInputElement).value))"/></label><label>高<input type="range" min="20" :max="1000" :value="box.h" @input="adjust('h',Number(($event.target as HTMLInputElement).value))"/></label><p v-if="error" role="alert">{{error}}</p></div><div v-if="box.w" class="reading-selection" :style="style"/><section v-if="readingMaterial" class="reading-preview"><h3>发送前预览</h3><img v-if="readingMaterial.image" :src="readingMaterial.image" alt="本次框选书页预览"/><pre>{{readingMaterial.text}}</pre><pre v-if="readingMaterial.latex">{{readingMaterial.latex}}</pre><p>只加入小E待发送材料，点击聊天发送后才上传。</p><button v-if="readingMaterial.image" @click="accept()">使用图文选区</button><button v-if="readingMaterial.text||readingMaterial.latex" @click="accept(true)">仅使用文字与公式</button><button @click="readingMaterial=null">重新框选</button></section></div></template>
<style>.frame-reading{position:fixed;inset:0;z-index:1400;cursor:crosshair;touch-action:none}.frame-reading-tools{position:absolute;bottom:8px;left:50%;transform:translateX(-50%);width:min(780px,95vw);padding:12px;background:#102239;color:#fff;border:2px solid #7ee3ef;z-index:2;max-height:35vh;overflow:auto;cursor:default}.frame-reading-tools label{display:inline-flex;font-size:12px}.frame-reading button{min-height:44px;margin:4px;padding:8px 14px;background:#183e54;color:white;border:1px solid #83d7e1}.reading-selection{position:fixed;border:2px solid #80efff;background:#5ae6ff18;box-shadow:0 0 0 9999px #0004;pointer-events:none}.reading-preview{position:fixed;right:16px;top:16px;width:min(430px,92vw);max-height:62vh;overflow:auto;z-index:3;padding:16px;background:#14283d;color:#fff;cursor:default;touch-action:auto}.reading-preview img{max-width:100%;max-height:220px;object-fit:contain}.reading-preview pre{white-space:pre-wrap;font-size:12px;max-height:100px;overflow:auto}.frame-reading [role=alert]{color:#ffc6c6}</style>
